import{c,J as l,h as s,k as r}from"./chunks/framework.NhpCCunm.js";const v=JSON.parse('{"title":"Онлайн-калькуляторы себестоимости продукции","description":"Бесплатные интерактивные калькуляторы расчёта себестоимости для мастеров, цехов и малых производств. Оцифровка сырья, брака, комплектующих и нормы-часа с экспортом смет в Excel.","frontmatter":{"title":"Онлайн-калькуляторы себестоимости продукции","description":"Бесплатные интерактивные калькуляторы расчёта себестоимости для мастеров, цехов и малых производств. Оцифровка сырья, брака, комплектующих и нормы-часа с экспортом смет в Excel."},"headers":[],"relativePath":"ru/calculators/index.md","filePath":"ru/calculators/index.md"}'),t={name:"ru/calculators/index.md"};function e(i,a,d,o,n,h){return l(),s("div",null,[...a[0]||(a[0]=[r('<h1 id="онлаин-калькуляторы-себестоимости-продукции" tabindex="-1">Онлайн-калькуляторы себестоимости продукции <a class="header-anchor" href="#онлаин-калькуляторы-себестоимости-продукции" aria-label="Permalink to &quot;Онлайн-калькуляторы себестоимости продукции&quot;">​</a></h1><p>Комплекс интерактивных инструментов для точного расчёта производственной себестоимости единицы товара. Инструменты созданы практикующими мастерами для малого бизнеса, частных цехов и ремесленных мастерских.</p><p>Каждый калькулятор автоматически учитывает фундаментальные статьи затрат, о которых чаще всего забывают при расчётах «на коленке»: скрытый процент технологических потерь и брака, расходные материалы, упаковку, амортизацию оборудования и реальную стоимость нормы-часа мастера.</p><h2 id="отраслевые-калькуляторы-и-технологические-карты" tabindex="-1">Отраслевые калькуляторы и технологические карты <a class="header-anchor" href="#отраслевые-калькуляторы-и-технологические-карты" aria-label="Permalink to &quot;Отраслевые калькуляторы и технологические карты&quot;">​</a></h2><p>Каждая сфера производства имеет свои скрытые статьи списания и технологические потери. Выберите подходящий специализированный инструмент с готовой сметой и экспортом в Excel:</p><div class="calc-grid"><div class="calc-card"><div class="calc-card-header"><div class="calc-icon-box"><svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z"></path><polyline points="3.27 6.96 12 12.01 20.73 6.96"></polyline><line x1="12" y1="22.08" x2="12" y2="12"></line></svg></div><div><h3 class="calc-card-title"><a href="/ru/calculators/product-cost-calculator">Универсальный калькулятор</a></h3><span class="calc-card-badge">Все виды товаров</span></div></div><p class="calc-card-desc"> Базовая модель калькуляции для сборочных, столярных, текстильных и смешанных производств. Расчёт чистого сырья, процента брака, комплектующих, упаковки, стоимости рабочего времени и амортизации станков. </p><div class="calc-card-footer"><span class="calc-feature">Экспорт сметы в Excel (.xlsx)</span><a href="/ru/calculators/product-cost-calculator" class="calc-btn">Открыть расчёт →</a></div></div><div class="calc-card"><div class="calc-card-header"><div class="calc-icon-box"><svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 6 2 18 2 18 9"></polyline><path d="M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2"></path><rect x="6" y="14" width="12" height="8"></rect></svg></div><div><h3 class="calc-card-title"><a href="/ru/calculators/3d-print-cost-calculator">3D-печать и мелкосерийка</a></h3><span class="calc-card-badge">FDM / SLA инженерия</span></div></div><p class="calc-card-desc"> Калькуляция стоимости печати на основе веса детали в слайсере, поддержек и продувочных башен (15–20%), закладных латунных втулок M3, амортизации сопла, наклейки PEI и электроэнергии. </p><div class="calc-card-footer"><span class="calc-feature">Учёт поддержек и брака</span><a href="/ru/calculators/3d-print-cost-calculator" class="calc-btn">Открыть расчёт →</a></div></div><div class="calc-card"><div class="calc-card-header"><div class="calc-icon-box"><svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M18 8h1a4 4 0 0 1 0 8h-1"></path><path d="M2 8h16v9a4 4 0 0 1-4 4H6a4 4 0 0 1-4-4V8z"></path><line x1="6" y1="1" x2="6" y2="4"></line><line x1="10" y1="1" x2="10" y2="4"></line><line x1="14" y1="1" x2="14" y2="4"></line></svg></div><div><h3 class="calc-card-title"><a href="/ru/calculators/dish-cost-calculator">Блюда и кулинария</a></h3><span class="calc-card-badge">Общепит и цеха</span></div></div><p class="calc-card-desc"> Построение технологической карты блюда: перевод брутто в нетто, термопотери на уварку и ужарку (до 35%), порционные специи, вакуумные пакеты, маркировка КБЖУ и норма-час повара. </p><div class="calc-card-footer"><span class="calc-feature">Расчёт термопотерь</span><a href="/ru/calculators/dish-cost-calculator" class="calc-btn">Открыть расчёт →</a></div></div><div class="calc-card"><div class="calc-card-header"><div class="calc-icon-box"><svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 2v4"></path><path d="M4.93 10.93l2.83 2.83"></path><path d="M2 18h20"></path><path d="M20 18v2a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2v-2"></path><path d="M4 18c0-4 4-7 8-7s8 3 8 7"></path></svg></div><div><h3 class="calc-card-title"><a href="/ru/calculators/cake-cost-calculator">Торты и выпечка</a></h3><span class="calc-card-badge">Кондитерское дело</span></div></div><p class="calc-card-desc"> Специализированная смета для кондитеров: сырьевой замес, упёк бисквитов в духовке (10–14%), крем-чиз, ягоды, усиленная влагостойкая подложка, высокая коробка и время сборки. </p><div class="calc-card-footer"><span class="calc-feature">Учёт упёка и коробки</span><a href="/ru/calculators/cake-cost-calculator" class="calc-btn">Открыть расчёт →</a></div></div><div class="calc-card"><div class="calc-card-header"><div class="calc-icon-box"><svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M8.5 14.5A2.5 2.5 0 0 0 11 12c0-1.38-.5-2-1-3-1.072-2.143-.224-4.054 2-6 .5 2.5 2 4.9 4 6.5 2 1.6 3 3.5 3 5.5a7 7 0 1 1-14 0c0-1.153.433-2.294 1-3a2.5 2.5 0 0 0 2.5 2.5z"></path></svg></div><div><h3 class="calc-card-title"><a href="/ru/calculators/candle-cost-calculator">Свечи и мыловарение</a></h3><span class="calc-card-badge">Хэндмейд и косметика</span></div></div><p class="calc-card-desc"> Пересчёт объёма банки в вес соевого или кокосового воска с учётом коэффициента плотности (0.86–0.90), точный процент ввода премиальных отдушек (8–10%), фитили и тара. </p><div class="calc-card-footer"><span class="calc-feature">Ввод отдушек и плотность</span><a href="/ru/calculators/candle-cost-calculator" class="calc-btn">Открыть расчёт →</a></div></div><div class="calc-card"><div class="calc-card-header"><div class="calc-icon-box"><svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01L12 2z"></path></svg></div><div><h3 class="calc-card-title"><a href="/ru/calculators/beauty-cost-calculator">Маникюр и бьюти-сфера</a></h3><span class="calc-card-badge">Ногтевой сервис</span></div></div><p class="calc-card-desc"> Точный расчёт себестоимости бьюти-процедуры: одноразовый абразивный комплект, расход баз и гель-лаков, крафт-пакеты стерилизации по нормам СанПиН и почасовая аренда кабинета. </p><div class="calc-card-footer"><span class="calc-feature">Стерилизация и аренда</span><a href="/ru/calculators/beauty-cost-calculator" class="calc-btn">Открыть расчёт →</a></div></div><div class="calc-card"><div class="calc-card-header"><div class="calc-icon-box"><svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M6 2L3 6v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V6l-3-4z"></path><line x1="3" y1="6" x2="21" y2="6"></line><path d="M16 10a4 4 0 0 1-8 0"></path></svg></div><div><h3 class="calc-card-title"><a href="/ru/calculators/leather-cost-calculator">Изделия из кожи</a></h3><span class="calc-card-badge">Кожевенное ремесло</span></div></div><p class="calc-card-desc"> Разбор себестоимости кожаных аксессуаров: оцифровка полезной площади шкуры, ловушка краевых обрезков (20–35%), итальянская химия, нитки, фурнитура и трудоёмкий седельный шов. </p><div class="calc-card-footer"><span class="calc-feature">Ловушка обрезков шкуры</span><a href="/ru/calculators/leather-cost-calculator" class="calc-btn">Открыть расчёт →</a></div></div></div><hr><h2 id="формула-полнои-производственнои-себестоимости" tabindex="-1">Формула полной производственной себестоимости <a class="header-anchor" href="#формула-полнои-производственнои-себестоимости" aria-label="Permalink to &quot;Формула полной производственной себестоимости&quot;">​</a></h2><p>Классическая формула расчёта, реализованная в представленных калькуляторах:</p><p>$$\\text{Себестоимость} = \\left(\\text{Сырьё} \\times (1 + \\text{Брак})\\right) + \\text{Фурнитура} + \\text{Упаковка} + (\\text{Время} \\times \\text{Ставка}) + \\text{Амортизация}$$</p><ol><li><strong>Сырьевая база:</strong> физический вес или объём основных материалов, скорректированный на коэффициент технологических потерь (обрезки, опилки, испарение, упёк, поддержки).</li><li><strong>Комплектующие и фурнитура:</strong> неделимые детали (молнии, кнопки, магниты, фитили, коробки, втулки, бирки).</li><li><strong>Прямой труд (ПЗТ):</strong> фактическое количество чистого рабочего времени мастера или оператора, умноженное на комфортную целевую ставку за час работы.</li><li><strong>Амортизация и инфраструктура:</strong> резерв на износ оборудования, замену расходных материалов и режущей оснастки (сопла, лезвия, сверла) и электроэнергию.</li></ol><p>Для расчёта отпускной розничной и оптовой цены с учётом маржи и наценки воспользуйтесь нашим руководством: <a href="/ru/articles/pricing-and-margins">Ценообразование, наценка и маржа: как рассчитать стоимость изделия и не работать в минус</a></p><hr><h2 id="от-онлаин-калькулятора-к-системному-учету" tabindex="-1">От онлайн-калькулятора к системному учёту <a class="header-anchor" href="#от-онлаин-калькулятора-к-системному-учету" aria-label="Permalink to &quot;От онлайн-калькулятора к системному учёту&quot;">​</a></h2><p>Онлайн-калькулятор незаменим для экспресс-оценки новой модели перед выставлением коммерческого предложения. Однако при постоянном потоке заказов ручной ввод формул в таблицы приводит к трем системным проблемам:</p><ul><li><strong>Рассинхронизация цен:</strong> сырьё дорожает, а старые расчёты в таблицах остаются неизменными.</li><li><strong>Потеря партионности:</strong> списание материалов происходит без учёта реальных цен закупки по средней скользящей (MAC).</li><li><strong>Разрыв между сметой и складом:</strong> рассчитав смету на бумаге, мастер забывает физически списать остаток с полки.</li></ul><p>Для решения этих задач создана локальная программа <strong>«ОмниКрафт ЕРП»</strong> — автономная система для мастеров и цехов, в которой калькулятор напрямую связан со складом сырья, витриной готовой продукции и финансовым потоком ДДС.</p><p><a href="/ru/articles/cost-calculation-software">Сравнение инструментов учёта: Excel, онлайн-калькуляторы и локальная ЕРП</a></p>',18)])])}const u=c(t,[["render",e]]);export{v as __pageData,u as default};
